import React, { useCallback, useEffect, useRef, useState } from "react"
import { Link } from "gatsby"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import Icon from "../components/ui/Icon"

import { TUTORIALS } from "../data/tutorials"

/**
 * Tutorials.
 *
 * Short silent recordings of the main tasks, as a playlist: one player, a
 * numbered list beside it, and the selected clip's contents underneath.
 *
 * WHY A PLAYLIST AND NOT A GRID OF PLAYERS. Five <video> elements on one page
 * is five sets of buffering, five sets of controls, and five things that can
 * be playing at once. One player and a list also mirrors how somebody works
 * through a tutorial set — in order, one at a time — rather than presenting
 * them as five unrelated files.
 *
 * WHY THE SILENCE IS ANNOUNCED. These recordings have no audio track. A viewer
 * who does not know that will assume the site is broken and start hunting
 * through their own volume settings. Saying so once, before anyone presses
 * play, costs a line and prevents that entirely.
 */

/** Seconds → m:ss. Read from the file, never typed in. */
function clock(seconds) {
  if (!Number.isFinite(seconds) || seconds <= 0) return null
  const m = Math.floor(seconds / 60)
  const s = Math.round(seconds % 60)
  return `${m}:${String(s).padStart(2, "0")}`
}

export default function TutorialsPage({ location }) {
  const [activeId, setActiveId] = useState(TUTORIALS[0]?.id ?? null)
  const [durations, setDurations] = useState({})
  const [failed, setFailed] = useState({})
  const videoRef = useRef(null)

  const active = TUTORIALS.find(t => t.id === activeId) || TUTORIALS[0]
  const activeIndex = TUTORIALS.findIndex(t => t.id === active?.id)

  /*
   * Durations come from the files themselves.
   *
   * `preload="metadata"` on each hidden probe pulls only the header, not the
   * dozen megabytes of video, so the list can show real runtimes without
   * downloading everything the moment the page opens.
   */
  const noteDuration = useCallback((id, value) => {
    setDurations(prev => (prev[id] === value ? prev : { ...prev, [id]: value }))
  }, [])

  /* Selecting a clip should start it — the click already said "play this". */
  useEffect(() => {
    const node = videoRef.current
    if (!node) return
    node.load()
  }, [activeId])

  const select = id => {
    setActiveId(id)
    // Scroll the player into view on narrow screens, where the list sits above
    // it and a selection would otherwise appear to do nothing.
    if (typeof window !== "undefined" && window.innerWidth < 900) {
      requestAnimationFrame(() => {
        videoRef.current?.scrollIntoView({ behavior: "smooth", block: "center" })
      })
    }
  }

  const goTo = delta => {
    const next = TUTORIALS[activeIndex + delta]
    if (next) select(next.id)
  }

  return (
    <Shell location={location} showTicker={false}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "Tutorials" }]} />
            <h1 className="page__title">Tutorials</h1>
            <p className="page__lede">
              Short recordings of the main tasks. Each one shows a single job from start to
              finish.
            </p>
          </div>
          <div className="page__aside">
            <span className="tut__silent">
              <Icon name="eye" size={14} />
              No audio — these are silent walkthroughs
            </span>
          </div>
        </header>

        <section className="section">
          <div className="tut">
            {/* ------------------------------------------------------ player */}
            <div className="tut__main">
              <div className="tut__stage">
                {failed[active.id] ? (
                  <div className="tut__missing">
                    <p className="tut__missing-title">This recording is not available</p>
                    <p className="tut__missing-text">
                      Expected at <code>{active.file}</code>. If the site was just deployed,
                      the video file may not have been included in the build.
                    </p>
                  </div>
                ) : (
                  <video
                    ref={videoRef}
                    className="tut__video"
                    controls
                    playsInline
                    preload="metadata"
                    onLoadedMetadata={e => noteDuration(active.id, e.currentTarget.duration)}
                    onError={() => setFailed(prev => ({ ...prev, [active.id]: true }))}
                  >
                    <source src={active.file} type="video/mp4" />
                    Your browser cannot play this video.
                  </video>
                )}
              </div>

              <div className="tut__meta">
                <div className="tut__meta-head">
                  <span className="tut__number">
                    {String(activeIndex + 1).padStart(2, "0")}
                  </span>
                  <div>
                    <h2 className="tut__title">{active.title}</h2>
                    <p className="tut__summary">{active.summary}</p>
                  </div>
                </div>

                <div className="tut__actions">
                  <button
                    type="button"
                    className="tut__nav"
                    onClick={() => goTo(-1)}
                    disabled={activeIndex <= 0}
                  >
                    Previous
                  </button>
                  <button
                    type="button"
                    className="tut__nav"
                    onClick={() => goTo(1)}
                    disabled={activeIndex >= TUTORIALS.length - 1}
                  >
                    Next
                  </button>
                  <Link className="tut__open" to={active.page}>
                    Open {active.pageLabel}
                    <Icon name="arrowUpRight" size={14} />
                  </Link>
                </div>
              </div>
            </div>

            {/* -------------------------------------------------------- list */}
            <aside className="tut__list" aria-label="Tutorials">
              <p className="tut__list-head">
                {TUTORIALS.length} recordings
              </p>

              <ol className="tut__items">
                {TUTORIALS.map((item, i) => {
                  const seconds = durations[item.id]
                  const length = clock(seconds)
                  return (
                    <li key={item.id}>
                      <button
                        type="button"
                        className={"tut__item" + (item.id === active.id ? " is-active" : "")}
                        onClick={() => select(item.id)}
                        aria-current={item.id === active.id ? "true" : undefined}
                      >
                        <span className="tut__item-num">{String(i + 1).padStart(2, "0")}</span>
                        <span className="tut__item-body">
                          <span className="tut__item-title">{item.title}</span>
                          <span className="tut__item-summary">{item.summary}</span>
                        </span>
                        <span className="tut__item-time">{length || ""}</span>
                      </button>

                      {/*
                        Metadata-only probe. Loads the header so the list can
                        show a real runtime, without pulling the video body.
                      */}
                      {seconds === undefined && !failed[item.id] && (
                        <video
                          preload="metadata"
                          muted
                          style={{ display: "none" }}
                          onLoadedMetadata={e => noteDuration(item.id, e.currentTarget.duration)}
                          onError={() => setFailed(prev => ({ ...prev, [item.id]: true }))}
                        >
                          <source src={item.file} type="video/mp4" />
                        </video>
                      )}
                    </li>
                  )
                })}
              </ol>
            </aside>
          </div>
        </section>

        {/* ------------------------------------------------------- contents */}
        <section className="section">
          <Panel title="What this recording covers" subtitle={active.title}>
            <ol className="tut__covers">
              {active.covers.map((step, i) => (
                <li key={i}>{step}</li>
              ))}
            </ol>
            <p className="tut__note">
              Written steps for every task are in <code>RECORDINGS.md</code>, and the full
              verification runbook is in <code>TESTING.md</code>.
            </p>
          </Panel>
        </section>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Tutorials · MarketScan</title>
